import CoreText
import Foundation

/// Unicode 17 keyboard order and names, generated by scripts/generate-reaction-emoji.py.
/// The source URL, digest, version, subgroup and original sequence order remain in the bundle.
@MainActor
struct ReactionEmojiCatalog {
    struct Entry: Decodable, Identifiable {
        let emoji: String
        let name: String
        let version: String
        let group: Int
        let subgroup: Int
        let order: Int
        let base: Int?

        var id: Int { order }

        private enum CodingKeys: String, CodingKey {
            case emoji = "e"
            case name = "n"
            case version = "v"
            case group = "g"
            case subgroup = "s"
            case order = "o"
            case base = "b"
        }
    }

    struct Group: Identifiable {
        let id: Int
        let entries: [Entry]
    }

    private struct Document: Decodable {
        let unicodeVersion: String
        let groups: [String]
        let subgroups: [String]
        let entries: [Entry]
    }

    enum LoadError: LocalizedError {
        case missingResource
        case invalidCatalog

        var errorDescription: String? {
            switch self {
            case .missingResource: "The bundled Unicode reaction catalog is missing."
            case .invalidCatalog: "The bundled Unicode reaction catalog is invalid."
            }
        }
    }

    static let bundled: Result<ReactionEmojiCatalog, Error> = Result {
        guard let url = Bundle.main.url(forResource: "reaction-emoji-17", withExtension: "json")
        else {
            throw LoadError.missingResource
        }
        let document = try JSONDecoder().decode(Document.self, from: Data(contentsOf: url))
        guard document.unicodeVersion == "17.0", document.groups.count == 9,
            !document.subgroups.isEmpty, !document.entries.isEmpty,
            document.entries.enumerated().allSatisfy({ index, entry in
                entry.order == index && document.groups.indices.contains(entry.group)
                    && document.subgroups.indices.contains(entry.subgroup)
                    && (entry.base.map { document.entries.indices.contains($0) } ?? true)
            })
        else { throw LoadError.invalidCatalog }
        return ReactionEmojiCatalog(document: document)
    }

    let groups: [Group]
    private let entriesByEmoji: [String: Entry]
    private let entriesByID: [Int: Entry]
    private let variantsByBase: [Int: [Entry]]

    private init(document: Document) {
        // Shape once with the installed Apple emoji font rather than guessing which
        // OS point release added an emoji. This also handles newer font updates.
        let support = ReactionEmojiGlyphSupport()
        let supported = document.entries.filter { support.supports($0.emoji) }
        let byID = Dictionary(uniqueKeysWithValues: supported.map { ($0.id, $0) })
        entriesByID = byID
        entriesByEmoji = Dictionary(uniqueKeysWithValues: supported.map { ($0.emoji, $0) })
        variantsByBase = Dictionary(
            grouping: supported.filter { $0.base.map { byID[$0] != nil } == true },
            by: { $0.base! })
        groups = document.groups.indices.map { group in
            Group(id: group, entries: supported.filter { $0.group == group && $0.base == nil })
        }
    }

    func entry(for emoji: String) -> Entry? {
        entriesByEmoji[emoji]
    }

    func variants(for entry: Entry) -> [Entry] {
        guard let baseID = entry.base, let base = entriesByID[baseID] else {
            return variantsByBase[entry.id] ?? []
        }
        return [base] + (variantsByBase[baseID] ?? []).filter { $0.id != entry.id }
    }
}

/// A single grapheme cluster is not proof of display support: unsupported ZWJ
/// sequences can still be one Swift Character while rendering as several emoji.
/// Require one visible, non-.notdef AppleColorEmoji glyph. Ignore only zero-advance
/// shaping artifacts; reject ignored modifiers/joiners/tags that merely show the
/// initial emoji (notably unsupported subdivision flags showing a black flag).
@MainActor
private struct ReactionEmojiGlyphSupport {
    private let font = CTFontCreateWithName("AppleColorEmoji" as CFString, 32, nil)

    func supports(_ emoji: String) -> Bool {
        guard let glyph = visibleGlyph(for: emoji) else { return false }
        let scalars = emoji.unicodeScalars
        let hasComposition = scalars.contains {
            $0.value == 0x200D || (0x1F3FB...0x1F3FF).contains($0.value)
                || (0xE0020...0xE007F).contains($0.value)
        }
        if hasComposition, let first = scalars.first,
            visibleGlyph(for: String(first)) == glyph
        {
            return false
        }
        return true
    }

    private func visibleGlyph(for text: String) -> CGGlyph? {
        let attributed = NSAttributedString(
            string: text,
            attributes: [NSAttributedString.Key(kCTFontAttributeName as String): font])
        let line = CTLineCreateWithAttributedString(attributed)
        var result: CGGlyph?
        for run in CTLineGetGlyphRuns(line) as! [CTRun] {
            let attributes = CTRunGetAttributes(run) as NSDictionary
            let runFont = attributes[kCTFontAttributeName] as! CTFont
            let isEmojiFont = (CTFontCopyPostScriptName(runFont) as String).contains(
                "AppleColorEmoji")
            for index in 0..<CTRunGetGlyphCount(run) {
                var glyph: CGGlyph = 0
                var advance = CGSize.zero
                let range = CFRange(location: index, length: 1)
                CTRunGetGlyphs(run, range, &glyph)
                CTRunGetAdvances(run, range, &advance)
                guard abs(advance.width) > 0.01 || abs(advance.height) > 0.01 else { continue }
                guard isEmojiFont, glyph != 0, result == nil else { return nil }
                result = glyph
            }
        }
        return result
    }
}
